function Digest([byte[]]$Bytes, [string]$Algorithm) {
 $h=[System.Security.Cryptography.HashAlgorithm]::Create($Algorithm)
 try { return ([BitConverter]::ToString($h.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant() } finally { $h.Dispose() }
}
function BlobId([byte[]]$Bytes) {
 [byte[]]$head=[Text.Encoding]::ASCII.GetBytes("blob $($Bytes.Length)"+[char]0)
 [byte[]]$obj=New-Object byte[] ($head.Length+$Bytes.Length)
 [Array]::Copy($head,0,$obj,0,$head.Length)
 [Array]::Copy($Bytes,0,$obj,$head.Length,$Bytes.Length)
 return Digest $obj 'SHA1'
}
function VerifyBatch($Expected,$Batch,[int]$MaxBytes) {
